def areEquivalent(a, b):
    """
    Check if the sum of divisors of a equals the sum of divisors of b.

    Args:
        a (int): First integer
        b (int): Second integer

    Returns:
        bool: True if sums are equal, False otherwise
    """
    def sum_of_divisors(n):
        total = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i * i != n:
                    total += n // i
        return total

    return sum_of_divisors(a) == sum_of_divisors(b)
